// provenance: original
"use client"

import { useId, useMemo, useRef, useState } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { MEASURE_REST, MeasureAnchor, MeasureBand, useMeasure } from "@/components/ui/chart-measure"
import { AxisTag } from "@/components/ui/chart-overlay"
import { SegmentedControl } from "@/components/ui/segmented-control"

/* Price Scrubber: the wide price chart (560px, the Price chart family's width).
   A magnet crosshair snaps to the real datum, the pointed price is tagged on the axis,
   and scrubbing reads the point into the header in place, recolouring the chart off the
   window's first price. A soft wash rides the cursor.
   2026-10-02 audit: brought into the one chart language. The header has the three tiers
   (spec 14.1): the name at /45 with the symbol at /90 on the right, the price at 26px with
   its cents at /35, then the move in its hue and the window ("past year", or the pointed
   time) at /45; a new `name` prop carries the company, and the sample is Broadcom (AVGO)
   so the two ends of the label row do not read the same. The pointed value is the shared
   AxisTag (it drew its own square badges) and the time badge on the foot is gone since the
   header reads the time. Gridlines are solid at 5%, the axis prints dollars at 9px /45,
   and the timeframe pills are the shared SegmentedControl in the header, not a hand made
   row under the plot.
   2026-11-10: a new `measure` prop (off by default) turns on drag to measure
   (chart-measure.tsx, shared with Candlestick). Press on the chart and drag sideways: the
   stretch between the press and the pointer lights up, the rest of the line rests at 0.45,
   and the header reads the stretch in place: the price at its later end, the move and the
   percent across it, and its two times. Letting go keeps it until the next press or
   Escape. From the keyboard the arrows point and Shift with an arrow measures.
   Formulas:
   · move = the pointed price (or the last) − the window's first price
   · percent = move ÷ the window's first price × 100
   · measured move = the stretch's later price − its earlier price
   · measured percent = measured move ÷ the stretch's earlier price × 100 */

const EASE = [0.16, 1, 0.3, 1] as const
const GREEN = "var(--chart-up)"
const RED = "var(--chart-down)"

const TF = ["1D", "1W", "1M", "1Y", "All"] as const
export type ScrubTimeframe = (typeof TF)[number]

const N: Record<ScrubTimeframe, number> = { "1D": 78, "1W": 84, "1M": 90, "1Y": 120, All: 150 }

/** Deterministic walk per timeframe (LCG); 1M trends down so red earns its keep. */
function makeSeries(tf: ScrubTimeframe): number[] {
  let s = 1000 + TF.indexOf(tf) * 733
  const n = N[tf]
  const drift = tf === "1M" ? -0.22 : 0.28
  let v = 178
  const out: number[] = []
  for (let i = 0; i < n; i++) {
    s = (s * 1103515245 + 12345) & 0x7fffffff
    v += (s / 0x7fffffff - 0.5) * 2.2 + drift * 0.08
    out.push(v)
  }
  return out
}

function timeLabel(tf: ScrubTimeframe, f: number): string {
  const clamp = (x: number, top: number) => Math.max(0, Math.min(top, x))
  switch (tf) {
    case "1D": {
      const m = 570 + Math.round(f * 390)
      return `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`
    }
    case "1W":
      return ["Mon", "Tue", "Wed", "Thu", "Fri"][clamp(Math.floor(f * 5), 4)]
    case "1M":
      return `Day ${1 + Math.round(f * 29)}`
    case "1Y":
      return ["Aug", "Sep", "Oct", "Nov", "Dec", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul"][clamp(Math.floor(f * 12), 11)]
    case "All":
      return `’${22 + clamp(Math.floor(f * 4), 4)}`
  }
}

const AXES: Record<ScrubTimeframe, string[]> = {
  "1D": ["09:30", "11:30", "13:30", "15:30"],
  "1W": ["Mon", "Wed", "Fri"],
  "1M": ["Wk 1", "Wk 2", "Wk 3", "Wk 4"],
  "1Y": ["Aug", "Nov", "Feb", "May"],
  All: ["’22", "’23", "’24", "’25", "’26"],
}

/** what the move is measured over, at rest */
const WINDOW: Record<ScrubTimeframe, string> = { "1D": "today", "1W": "past week", "1M": "past month", "1Y": "past year", All: "all time" }

const axisUsd = (n: number) => `$${Math.round(n).toLocaleString("en-US")}`
const fmtPrice = (n: number) => `$${n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

const W = 560
const H = 220
const PAD = { l: 10, r: 66, t: 18, b: 26 }
const PLOT_W = W - PAD.l - PAD.r
const PLOT_H = H - PAD.t - PAD.b

/* the hover wash: half-width of the falloff in svg units and how far the rest of
   the series drops back while it is lit; the ramp plateaus around the cursor
   and tails off steeply, peaking under 1 so it reads as brightness, not bloom */
const SPOT = 215
const SPOT_DIM = 0.2
const SPOT_STOPS: [number, number][] = [
  [0, 0],
  [0.1, 0],
  [0.22, 0.05],
  [0.32, 0.2],
  [0.4, 0.5],
  [0.5, 0.78],
  [0.6, 0.5],
  [0.68, 0.2],
  [0.78, 0.05],
  [0.9, 0],
  [1, 0],
]

/**
 * The scrub chart: a magnet crosshair snaps to the real datum with the price
 * tagged on the axis, and scrubbing updates the header, which recolours the
 * whole chart off the reference price. A soft wash rides the
 * cursor, so the line reads lighter under the pointer and settles back on the
 * far sides. Timeframe pills morph the chart in place. With `measure` on, a press dragged
 * sideways lights the stretch under it and the header reads the move across that stretch.
 */
export function PriceScrubber({
  name = "Broadcom",
  symbol = "AVGO",
  timeframe = "1Y",
  measure = false,
  className,
}: {
  /** the company or market's name, on the label row's left */
  name?: string
  symbol?: string
  /** the timeframe the chart opens on */
  timeframe?: ScrubTimeframe
  /** press and drag sideways to measure the move across a stretch; it stays until the next press or Escape */
  measure?: boolean
  className?: string
}) {
  const reduced = useReducedMotion()
  const uid = useId().replace(/:/g, "")
  const svgRef = useRef<SVGSVGElement>(null)
  const [tf, setTf] = useState<ScrubTimeframe>(timeframe)

  const data = useMemo(() => makeSeries(tf), [tf])
  const n = data.length
  const { min, max } = useMemo(() => {
    const lo = Math.min(...data)
    const top = Math.max(...data)
    const pad = (top - lo) * 0.08
    return { min: lo - pad, max: top + pad }
  }, [data])

  const x = (i: number) => PAD.l + (i / (n - 1)) * PLOT_W
  const y = (v: number) => PAD.t + (1 - (v - min) / (max - min || 1)) * PLOT_H

  /* pointing reads one datum; with `measure` on, a press dragged sideways measures a stretch (chart-measure.tsx) */
  const { hi, span, point, bind, reset } = useMeasure({
    ref: svgRef,
    width: W,
    at: (px) => Math.round(((px - PAD.l) / PLOT_W) * (n - 1)),
    count: n,
    enabled: measure,
  })

  /* the header reads a window: the measured stretch, else the window's start to the pointed price (or the last) */
  const fromIdx = span ? span.from : 0
  const activeIdx = span ? span.to : (hi ?? n - 1)
  const reference = data[fromIdx]
  const activeVal = data[activeIdx]
  const delta = activeVal - reference
  const deltaPct = (delta / reference) * 100
  const up = delta >= 0
  const hue = up ? GREEN : RED

  const line = data.map((v, idx) => `${idx === 0 ? "M" : "L"}${x(idx).toFixed(1)},${y(v).toFixed(1)}`).join(" ")
  const area = `${line} L${x(n - 1).toFixed(1)},${H - PAD.b} L${x(0).toFixed(1)},${H - PAD.b} Z`
  /* the crosshair stands on the pointed datum, or on a measure's moving end */
  const crossIdx = point ?? n - 1
  const crossVal = data[crossIdx]
  const badgeY = y(crossVal)
  const crossX = x(crossIdx)
  const fromLabel = timeLabel(tf, fromIdx / (n - 1))
  const toLabel = timeLabel(tf, activeIdx / (n - 1))
  const tagY = Math.max(PAD.t + 8, Math.min(H - PAD.b - 8, badgeY))
  const [whole, cents] = fmtPrice(activeVal).split(".")

  return (
    <div className={cn("w-[560px]", className)}>
      {/* the header, three tiers (spec 14.1); scrubbing reads the point in place, the timeframe switch sits on its right */}
      <div className="mb-3 flex items-baseline justify-between text-[12px]">
        <span className="truncate text-foreground/45">{name}</span>
        <span className="shrink-0 pl-3 font-medium text-foreground/90">{symbol}</span>
      </div>
      <div className="mb-2 flex items-end justify-between gap-4 tabular-nums" role="status">
        <div>
          <p className="m-0 text-[26px] font-semibold leading-none tracking-[-0.02em] text-foreground/90">
            {whole}
            <span className="text-foreground/35">.{cents}</span>
          </p>
          <p className="mb-0 mt-2 flex items-baseline gap-[7px] text-[12px] font-medium" style={{ color: hue }}>
            <span>
              {up ? "+" : "−"}
              {fmtPrice(Math.abs(delta))} · {up ? "+" : "−"}
              {Math.abs(deltaPct).toFixed(2)}%
            </span>
            <span className="font-normal text-foreground/45">
              {span ? (fromLabel === toLabel ? toLabel : `${fromLabel} to ${toLabel}`) : hi === null ? WINDOW[tf] : toLabel}
            </span>
          </p>
        </div>
        <SegmentedControl
          options={[...TF]}
          value={tf}
          onChange={(v) => {
            setTf(v as ScrubTimeframe)
            reset()
          }}
          label="Timeframe"
          className="shrink-0"
        />
      </div>

      <svg
        ref={svgRef}
        width={W}
        height={H}
        viewBox={`0 0 ${W} ${H}`}
        className={cn("block cursor-crosshair touch-none", measure && "select-none outline-none")}
        role="img"
        aria-label={`${name} (${symbol}) price over the ${WINDOW[tf]}, ${fmtPrice(data[n - 1])}`}
        {...bind}
      >
        <defs>
          <linearGradient id={`${uid}-fill`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={hue} stopOpacity="0.16" />
            <stop offset="100%" stopColor={hue} stopOpacity="0" />
          </linearGradient>
          <linearGradient id={`${uid}-hot`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={hue} stopOpacity="0.24" />
            <stop offset="100%" stopColor={hue} stopOpacity="0" />
          </linearGradient>
        </defs>

        {[0.25, 0.5, 0.75].map((f) => {
          const gy = PAD.t + f * PLOT_H
          /* a figure steps aside while the pointed tag sits on it */
          const under = point !== null && Math.abs(gy - tagY) < 12
          return (
            <g key={f}>
              <line x1={PAD.l} y1={gy} x2={W - PAD.r} y2={gy} stroke="var(--foreground)" strokeOpacity={0.05} />
              <text
                x={W - PAD.r + 8}
                y={gy + 3}
                fontSize={9}
                fill="var(--foreground)"
                fillOpacity={0.45}
                className="tabular-nums"
                style={{ opacity: under ? 0 : 1, transition: reduced ? "none" : "opacity 150ms" }}
              >
                {axisUsd(max - f * (max - min))}
              </text>
            </g>
          )
        })}

        {AXES[tf].map((t, idx, arr) => (
          <text key={t} x={PAD.l + (idx / (arr.length - 1)) * PLOT_W} y={H - 8} textAnchor={idx === 0 ? "start" : idx === arr.length - 1 ? "end" : "middle"} fontSize={9} fill="var(--foreground)" fillOpacity={0.45}>
            {t}
          </text>
        ))}

        {/* area and line, re-keyed on the timeframe so they redraw; they sit back while scrubbing, and rest at 0.45 around a measured stretch */}
        <g opacity={span ? MEASURE_REST : hi === null ? 1 : SPOT_DIM} style={{ transition: reduced ? "none" : "opacity 0.22s" }}>
          <motion.path key={`a-${tf}`} d={area} fill={`url(#${uid}-fill)`} initial={{ opacity: reduced ? 1 : 0 }} animate={{ opacity: 1 }} transition={reduced ? { duration: 0 } : { duration: 0.4, ease: EASE, delay: 0.35 }} />
          <motion.path key={`l-${tf}`} d={line} fill="none" stroke={hue} strokeWidth={1.8} strokeLinejoin="round" initial={{ pathLength: reduced ? 1 : 0 }} animate={{ pathLength: 1 }} transition={reduced ? { duration: 0 } : { duration: 0.85, ease: EASE }} />
        </g>

        {/* the wash: a full-strength copy revealed through a mask that rides the cursor */}
        <AnimatePresence>
          {hi !== null && !span && (
            <motion.g key="spot" pointerEvents="none" initial={{ opacity: reduced ? 1 : 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, transition: { duration: reduced ? 0 : 0.16 } }} transition={reduced ? { duration: 0 } : { duration: 0.2, ease: EASE }}>
              <defs>
                <linearGradient id={`${uid}-ramp`} gradientUnits="userSpaceOnUse" x1={crossX - SPOT} y1="0" x2={crossX + SPOT} y2="0">
                  {SPOT_STOPS.map(([offset, o]) => (
                    // oxlint-disable-next-line shadcn/no-raw-colors -- mask stop: a mask reads luminance, so it stays white in both themes
                    <stop key={offset} offset={`${offset * 100}%`} stopColor="white" stopOpacity={o} />
                  ))}
                </linearGradient>
                <mask id={`${uid}-mask`} maskUnits="userSpaceOnUse" x={0} y={0} width={W} height={H}>
                  <rect x={0} y={0} width={W} height={H} fill={`url(#${uid}-ramp)`} />
                </mask>
              </defs>
              <g mask={`url(#${uid}-mask)`}>
                <path d={area} fill={`url(#${uid}-hot)`} />
                <path d={line} fill="none" stroke={hue} strokeWidth={1.8} strokeLinejoin="round" />
              </g>
            </motion.g>
          )}
        </AnimatePresence>

        {/* the measured stretch: a band in the move's hue and the series at full strength inside it (chart-measure.tsx) */}
        <MeasureBand span={span} x={x} top={PAD.t} bottom={H - PAD.b} color={hue}>
          <path d={area} fill={`url(#${uid}-hot)`} />
          <path d={line} fill="none" stroke={hue} strokeWidth={1.8} strokeLinejoin="round" />
        </MeasureBand>

        {/* magnet crosshair: rule, snapped dot and the pointed price tagged on the axis (chart-overlay.tsx); a measure adds the rule where its press landed */}
        {point !== null && (
          <g pointerEvents="none">
            <MeasureAnchor span={span} x={x} top={PAD.t} bottom={H - PAD.b} />
            <line x1={crossX} y1={PAD.t} x2={crossX} y2={H - PAD.b} stroke="var(--foreground)" strokeOpacity={0.2} strokeWidth={1} />
            <line x1={PAD.l} y1={badgeY} x2={W - PAD.r} y2={badgeY} stroke="var(--foreground)" strokeOpacity={0.14} strokeDasharray="3 3" strokeWidth={1} />
            <circle cx={crossX} cy={badgeY} r={3.5} fill={hue} stroke="var(--background)" strokeWidth={1.75} />
            <AxisTag x={W - PAD.r + 4} y={tagY} width={58} color={hue}>
              {fmtPrice(crossVal)}
            </AxisTag>
          </g>
        )}
      </svg>
    </div>
  )
}

// provenance: original
"use client"

import { useEffect, useId, useMemo, useRef, useState, type FocusEvent, type KeyboardEvent, type PointerEvent, type ReactNode, type RefObject } from "react"

/* Chart measure: press on a chart and drag sideways to measure a stretch of it (2026-11-10).
   The one copy for Price Scrubber and Candlestick, so the two read as one tool; it ships
   beside the charts that use it.

   useMeasure     the pointing and the measuring on a chart's svg. Pointing reads one index
                  (`hi`), as the charts did before. A press that travels 4px sideways becomes
                  a measure between the pressed index and the pointer's; the pointer is
                  captured, so the drag carries on past the chart's edge. Letting go keeps the
                  measure, and it then owns the readout: the next press or Escape lets it go.
                  From the keyboard the arrows point, Shift with an arrow measures, Home and
                  End jump to the ends.
   MeasureBand    the lit stretch: a band in the move's hue at 8% between the two ends, and
                  whatever it is handed drawn inside the stretch only (a line's full strength
                  copy). What sits outside rests at MEASURE_REST.
   MeasureAnchor  the rule where the press landed: 1px of ink at /20, the crosshair's twin.

   Motion: the band fades in over 150ms and out over 120ms (leave faster than you came).
   Its edges are plain attributes, so they sit on the pointer with no tween, and the figures
   a measure changes are reads that swap in place. A measure made from the keyboard appears
   and leaves at once. Reduced motion keeps the two fades, since nothing travels. */

const EASE_CSS = "cubic-bezier(0.16, 1, 0.3, 1)"
/** px of sideways travel before a press becomes a measure (--distance-micro), so a click never does */
const START = 4
/** what sits outside a measured stretch rests here (the house rest dim) */
export const MEASURE_REST = 0.45

export interface MeasureSpan {
  /** one per measure */
  id: number
  /** the index the press landed on, and the one under the pointer */
  a: number
  b: number
  /** the same two in time order */
  from: number
  to: number
  /** made from the keyboard, so it appears with no fade */
  instant: boolean
}

/** pointing and drag-to-measure for a chart's svg; spread `bind` on the svg */
export function useMeasure({
  ref,
  width,
  at,
  count,
  enabled = false,
}: {
  ref: RefObject<SVGSVGElement | null>
  /** the chart's width in its own units (the viewBox) */
  width: number
  /** the index under an x given in the chart's own units; clamped to the series here */
  at: (px: number) => number
  /** how many points or bars the series has */
  count: number
  /** off: the chart only points, exactly as it did before */
  enabled?: boolean
}) {
  const [pointed, setHi] = useState<number | null>(null)
  const [held, setHeld] = useState<{ id: number; a: number; b: number; instant: boolean } | null>(null)
  /* the press in flight: its pointer, where it landed, and its measure's id once it has travelled */
  const press = useRef<{ pointer: number; x: number; i: number; id: number } | null>(null)
  const serial = useRef(0)
  const last = count - 1

  /* a series that got shorter lets go of a point or a measure it no longer has */
  const hi = pointed !== null && pointed <= last ? pointed : null
  const span = useMemo<MeasureSpan | null>(
    () => (enabled && held && held.a <= last && held.b <= last ? { ...held, from: Math.min(held.a, held.b), to: Math.max(held.a, held.b) } : null),
    [enabled, held, last],
  )
  const on = span !== null

  /* Escape lets a measure go wherever the focus is. The listener sits on the chart's own
     document, since a preview frame's keys never reach the page that holds it. */
  useEffect(() => {
    if (!on) return
    const doc = ref.current?.ownerDocument ?? document
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key !== "Escape") return
      press.current = null
      setHeld(null)
    }
    doc.addEventListener("keydown", onKey)
    return () => doc.removeEventListener("keydown", onKey)
  }, [on, ref])

  const locate = (clientX: number) => {
    const el = ref.current
    if (!el || count === 0) return null
    const r = el.getBoundingClientRect()
    return Math.max(0, Math.min(last, at(((clientX - r.left) / (r.width || 1)) * width)))
  }

  const move = (e: PointerEvent<SVGSVGElement>) => {
    const i = locate(e.clientX)
    if (i === null) return
    setHi(i)
    const p = press.current
    if (!p || p.pointer !== e.pointerId) return
    if (!p.id && Math.abs(e.clientX - p.x) >= START) p.id = ++serial.current
    const id = p.id
    if (id) setHeld((s) => (s && s.id === id && s.b === i ? s : { id, a: p.i, b: i, instant: false }))
  }

  const down = (e: PointerEvent<SVGSVGElement>) => {
    /* one pointer measures: a second finger or another button is not a new press */
    if (!e.isPrimary || e.button !== 0 || press.current) return
    const i = locate(e.clientX)
    if (i === null) return
    press.current = { pointer: e.pointerId, x: e.clientX, i, id: 0 }
    e.currentTarget.setPointerCapture?.(e.pointerId)
    /* the next press lets the last measure go, whether it turns out a click or a new drag */
    setHeld(null)
    setHi(i)
  }

  const up = (e: PointerEvent<SVGSVGElement>) => {
    const p = press.current
    if (!p || p.pointer !== e.pointerId) return
    press.current = null
    if (e.currentTarget.hasPointerCapture?.(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId)
    /* a drag that came back to where it started measured nothing */
    setHeld((s) => (s && s.id === p.id && s.a === s.b ? null : s))
  }

  const leave = () => {
    if (!press.current) setHi(null)
  }

  const key = (e: KeyboardEvent<SVGSVGElement>) => {
    if (e.key === "Escape") {
      /* the document listener lets a measure go; with none held, Escape puts the crosshair away */
      if (!on) setHi(null)
      return
    }
    const by = e.key === "ArrowLeft" ? -1 : e.key === "ArrowRight" ? 1 : e.key === "Home" ? -count : e.key === "End" ? count : 0
    if (!by || count === 0) return
    e.preventDefault()
    const from = span ? span.b : (hi ?? last)
    const next = Math.max(0, Math.min(last, from + by))
    setHi(next)
    setHeld(e.shiftKey ? { id: span ? span.id : ++serial.current, a: span ? span.a : from, b: next, instant: true } : null)
  }

  /* focus from the keyboard reads the last point, the way pointing would */
  const focus = (e: FocusEvent<SVGSVGElement>) => {
    if (hi === null && count > 0 && e.currentTarget.matches(":focus-visible")) setHi(last)
  }

  const reset = () => {
    press.current = null
    setHi(null)
    setHeld(null)
  }

  const bind = enabled
    ? {
        onPointerDown: down,
        onPointerMove: move,
        onPointerUp: up,
        onPointerCancel: up,
        onPointerLeave: leave,
        onKeyDown: key,
        onFocus: focus,
        onBlur: leave,
        tabIndex: 0,
        "aria-keyshortcuts": "ArrowLeft ArrowRight Shift+ArrowLeft Shift+ArrowRight Home End Escape",
      }
    : { onPointerMove: move, onPointerLeave: leave }

  return {
    /** the pointed index, or null */
    hi,
    /** the measured stretch, or null */
    span,
    /** where the crosshair stands: the measure's moving end, else the pointed index */
    point: span ? span.b : hi,
    bind,
    /** puts the pointing and the measure away (a new series) */
    reset,
  }
}

/** the lit stretch of a measure; draw it in the chart's svg, under the crosshair */
export function MeasureBand({
  span,
  x,
  top,
  bottom,
  color,
  children,
}: {
  span: MeasureSpan | null
  /** an index's x in the chart's own units */
  x: (i: number) => number
  /** the band's top and bottom in the chart's own units */
  top: number
  bottom: number
  /** the measured move's hue */
  color: string
  /** drawn at full strength inside the stretch only: a line chart's lit copy */
  children?: ReactNode
}) {
  const uid = useId().replace(/:/g, "")
  /* the last measure stays drawn while it fades out, with what it lit */
  const [kept, setKept] = useState<{ span: MeasureSpan; x1: number; w: number; color: string; children: ReactNode } | null>(null)
  const live = span ? { span, x1: x(span.from), w: Math.max(0, x(span.to) - x(span.from)), color, children } : null
  if (live && live.span !== kept?.span) setKept(live)
  /* a measure made from the keyboard also leaves at once: keys get no animation */
  if (!live && kept?.span.instant) setKept(null)
  const s = live ?? kept

  return (
    <g
      data-measure={span ? `${span.from}-${span.to}` : undefined}
      pointerEvents="none"
      style={{
        opacity: span ? 1 : 0,
        transition: span ? (span.instant ? "none" : `opacity 150ms ${EASE_CSS}`) : `opacity 120ms ${EASE_CSS}`,
      }}
      onTransitionEnd={() => {
        if (!span) setKept(null)
      }}
    >
      {s && (
        <>
          <rect x={s.x1} y={top} width={s.w} height={bottom - top} style={{ fill: `color-mix(in srgb, ${s.color} 8%, transparent)` }} />
          {s.children && (
            <>
              <clipPath id={`${uid}-span`}>
                <rect x={s.x1} y={top - 4} width={s.w} height={bottom - top + 8} />
              </clipPath>
              <g clipPath={`url(#${uid}-span)`}>{s.children}</g>
            </>
          )}
        </>
      )}
    </g>
  )
}

/** the rule where a measure's press landed; it comes and goes with no animation */
export function MeasureAnchor({ span, x, top, bottom }: { span: MeasureSpan | null; x: (i: number) => number; top: number; bottom: number }) {
  if (!span) return null
  return <line x1={x(span.a)} y1={top} x2={x(span.a)} y2={bottom} stroke="var(--foreground)" strokeOpacity={0.2} strokeWidth={1} pointerEvents="none" />
}

// provenance: original
"use client"

import { type ReactNode } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

/* Chart overlay: the two parts every library chart reads a point with (2026-10-02). They
   came out of Candlestick, Volume Profile, the trading terminal and Price Scrubber, which
   had each drawn their own; this is the one copy. Shipped beside the charts that use it.

   AxisTag   the outlined tag on the value axis: the pointed value in its hue, or a named
             reference (POC, last close) in ink. A pill 16px high, 8.5px figures.
   ChartCard the card laid over the chart beside the cursor: a heading row (a time or a
             range) at /60, then label and value rows (labels 10px /60, values 11px /90),
             the one signed figure in its hue. It glides between points on a spring, fades
             in from 0.97 and out in 120ms, and flips to the cursor's left when told to.

   2026-10-02: the card looked out of place over the charts, so it now wears the library
   popover, the same as the sidebar's hover card: a hairline border at 8%, radius 9, the
   6% foreground mix and the popover shadow with no inset highlight (spec 14.6). */

const EASE = [0.16, 1, 0.3, 1] as const
const GLIDE = { type: "spring", stiffness: 520, damping: 40 } as const

/** the outlined tag on a chart's value axis, centred on `y` */
export function AxisTag({
  x,
  y,
  width,
  color = "var(--foreground)",
  strong = true,
  hidden = false,
  children,
}: {
  /** the tag's left edge, in the chart's own units */
  x: number
  /** the value's line; the tag is centred on it */
  y: number
  width: number
  /** stroke and figure; ink for a named reference, the series hue for the pointed value */
  color?: string
  /** a quieter tag (a secondary reference) drops the weight and the stroke */
  strong?: boolean
  /** fades the tag out, for when the pointed value sits on it */
  hidden?: boolean
  children: ReactNode
}) {
  return (
    <g transform={`translate(${x}, ${y - 8})`} pointerEvents="none" style={{ opacity: hidden ? 0 : 1, transition: "opacity 150ms" }}>
      <rect width={width} height={16} rx={8} fill="var(--background)" stroke={color} strokeOpacity={strong ? 0.6 : 0.2} />
      <text x={width / 2} y={11} textAnchor="middle" fontSize={8.5} fontWeight={strong ? 600 : 500} fill={color} fillOpacity={strong ? 1 : 0.65}>
        {children}
      </text>
    </g>
  )
}

export interface ChartCardRow {
  label: string
  value: ReactNode
  /** only the one signed figure carries a hue */
  color?: string
}

/** the readout card over a chart; place it inside a `relative` box that holds the svg */
export function ChartCard({
  open,
  x,
  y = 4,
  flip = false,
  width = 148,
  heading,
  rows,
  footer,
}: {
  open: boolean
  /** the cursor's x inside the box: px, or a percentage string for a chart drawn to a viewBox */
  x: number | string
  /** the card's top inside the box, px */
  y?: number
  /** put the card on the cursor's left (past ~60% of the plot) */
  flip?: boolean
  width?: number
  heading: ReactNode
  rows: ChartCardRow[]
  /** a closing line under the rows, such as where the point sits */
  footer?: ReactNode
}) {
  const reduced = useReducedMotion()
  return (
    <AnimatePresence>
      {open && (
        <motion.div
          key="chart-card"
          role="status"
          className="pointer-events-none absolute z-10"
          initial={{ left: x, top: y, opacity: 0 }}
          animate={{ left: x, top: y, opacity: 1 }}
          exit={{ opacity: 0, transition: { duration: 0.12 } }}
          transition={reduced ? { duration: 0 } : { left: GLIDE, top: GLIDE, opacity: { duration: 0.15 } }}
        >
          <motion.div
            className="rounded-[9px] border border-foreground/[0.08] px-3 py-2.5"
            style={{
              width,
              translate: flip ? "calc(-100% - 12px) 0" : "12px 0",
              transition: reduced ? undefined : "translate 200ms cubic-bezier(0.16, 1, 0.3, 1)",
              background: "var(--tip-fill, color-mix(in srgb, var(--foreground) 6%, var(--background)))",
              boxShadow: "0 8px 24px var(--card-shadow, rgba(0,0,0,calc(0.35 * var(--shadow-k, 1))))",
            }}
            initial={reduced ? false : { scale: 0.97 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.15, ease: EASE }}
          >
            <div className="text-[10px] text-foreground/60">{heading}</div>
            <div className="mt-1.5 flex flex-col gap-1">
              {rows.map((r) => (
                <div key={r.label} className="flex items-center justify-between gap-3">
                  <span className="text-[10px] text-foreground/60">{r.label}</span>
                  <span className="text-[11px] text-foreground/90" style={r.color ? { color: r.color } : undefined}>
                    {r.value}
                  </span>
                </div>
              ))}
            </div>
            {footer && <div className="mt-1.5 text-[10px]">{footer}</div>}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}
